import fs from 'fs';
import path from 'path';
import mysql, { type RowDataPacket } from 'mysql2/promise';
import { config } from '../config/env.js';
import type {
  Warehouse,
  Officer,
  Commodity,
  Stack,
  FumigationExercise,
  FumigationExerciseStackSnapshot,
  FumigationChallenge,
} from '../types/index.js';

export interface DatabaseState {
  warehouses: Warehouse[];
  officers: Officer[];
  commodities: Commodity[];
  stacks: Stack[];
  fumigation_exercises: FumigationExercise[];
  fumigation_exercise_stacks: FumigationExerciseStackSnapshot[];
  fumigation_challenges: FumigationChallenge[];
  nextIds: {
    warehouses: number;
    officers: number;
    commodities: number;
    stacks: number;
    fumigation_exercises: number;
    fumigation_exercise_stacks: number;
    fumigation_challenges: number;
  };
}

const SCHEMA_PATH = path.join(process.cwd(), 'db', 'schema.sql');

// Initial default seed dataset
export function getDefaultSeedData(): DatabaseState {
  return {
    warehouses: [],
    officers: [],
    commodities: [],
    stacks: [],
    fumigation_exercises: [],
    fumigation_exercise_stacks: [],
    fumigation_challenges: [],
    nextIds: {
      warehouses: 1,
      officers: 1,
      commodities: 1,
      stacks: 1,
      fumigation_exercises: 1,
      fumigation_exercise_stacks: 1,
      fumigation_challenges: 1,
    },
  };
}

class RelationalDatabaseManager {
  private state: DatabaseState = getDefaultSeedData();
  private mysqlPool: mysql.Pool | null = null;
  private isUsingMysql: boolean = false;

  constructor() {
    this.initializeDatabase().catch((error) => {
      console.error('[Database] Initial database bootstrap failed:', error);
    });
  }

  private async initializeDatabase(): Promise<void> {
    if (!config.db.host || !config.db.user || !config.db.database) {
      throw new Error('MySQL configuration is required. Set DB_HOST, DB_USER, DB_NAME, and DB_PASSWORD in the backend .env file.');
    }

    const basePool = mysql.createPool({
      host: config.db.host,
      port: config.db.port || 3306,
      user: config.db.user,
      password: config.db.password,
      multipleStatements: true,
    });

    try {
      await basePool.query(`CREATE DATABASE IF NOT EXISTS \`${config.db.database}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
    } finally {
      await basePool.end();
    }

    this.mysqlPool = mysql.createPool({
      host: config.db.host,
      port: config.db.port || 3306,
      user: config.db.user,
      password: config.db.password,
      database: config.db.database,
      waitForConnections: true,
      connectionLimit: 10,
      queueLimit: 0,
      multipleStatements: true,
    });

    try {
      const schemaSql = fs.readFileSync(SCHEMA_PATH, 'utf-8');
      const connection = await this.mysqlPool.getConnection();
      try {
        await connection.query(schemaSql);
      } finally {
        connection.release();
      }

      this.state = await this.loadStateFromDatabase();
      if (this.state.warehouses.length === 0 && this.state.officers.length === 0 && this.state.commodities.length === 0) {
        this.state = getDefaultSeedData();
        await this.persistState(this.state);
      }

      this.isUsingMysql = true;
      console.log(`[Database] Connected successfully to MySQL instance at ${config.db.host}:${config.db.port || 3306}/${config.db.database}`);
    } catch (error) {
      this.isUsingMysql = false;
      console.error('[Database] MySQL connection failed. Please verify the DB is running and the credentials are correct.', (error as Error).message);
      throw error;
    }
  }

  private async loadStateFromDatabase(): Promise<DatabaseState> {
    if (!this.mysqlPool) {
      return getDefaultSeedData();
    }

    const [warehousesRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM warehouses ORDER BY id ASC');
    const [officersRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM officers ORDER BY id ASC');
    const [commoditiesRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM commodities ORDER BY id ASC');
    const [stacksRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM stacks ORDER BY id ASC');
    const [exercisesRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM fumigation_exercises ORDER BY id ASC');
    const [snapshotsRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM fumigation_exercise_stacks ORDER BY id ASC');
    const [challengesRaw] = await this.mysqlPool.query<RowDataPacket[]>('SELECT * FROM fumigation_challenges ORDER BY id ASC');

    const nextWarehouses = Math.max(1, ...warehousesRaw.map((row) => Number(row.id))) + 1;
    const nextOfficers = Math.max(1, ...officersRaw.map((row) => Number(row.id))) + 1;
    const nextCommodities = Math.max(1, ...commoditiesRaw.map((row) => Number(row.id))) + 1;
    const nextStacks = Math.max(1, ...stacksRaw.map((row) => Number(row.id))) + 1;
    const nextExercises = Math.max(1, ...exercisesRaw.map((row) => Number(row.id))) + 1;
    const nextSnapshots = Math.max(1, ...snapshotsRaw.map((row) => Number(row.id))) + 1;
    const nextChallenges = Math.max(1, ...challengesRaw.map((row) => Number(row.id))) + 1;

    return {
      warehouses: (warehousesRaw as Warehouse[]).map((w) => ({ ...w, is_active: Number(w.is_active) })),
      officers: (officersRaw as Officer[]).map((o) => ({ ...o, is_active: Number(o.is_active), phone: o.phone ?? null })),
      commodities: (commoditiesRaw as Commodity[]).map((c) => ({ ...c, is_active: Number(c.is_active) })),
      stacks: (stacksRaw as Stack[]).map((s) => ({ ...s, current_quantity: Number(s.current_quantity), warehouse_id: Number(s.warehouse_id), commodity_id: Number(s.commodity_id) })),
      fumigation_exercises: (exercisesRaw as FumigationExercise[]).map((e) => ({ ...e, warehouse_id: Number(e.warehouse_id), responsible_officer_id: Number(e.responsible_officer_id), planned_duration: Number(e.planned_duration) })),
      fumigation_exercise_stacks: (snapshotsRaw as FumigationExerciseStackSnapshot[]).map((s) => ({ ...s, fumigation_exercise_id: Number(s.fumigation_exercise_id), stack_id: Number(s.stack_id), commodity_id: Number(s.commodity_id), quantity_snapshot: Number(s.quantity_snapshot) })),
      fumigation_challenges: (challengesRaw as FumigationChallenge[]).map((c) => ({ ...c, fumigation_exercise_id: Number(c.fumigation_exercise_id), resolved: Number(c.resolved) })),
      nextIds: {
        warehouses: nextWarehouses,
        officers: nextOfficers,
        commodities: nextCommodities,
        stacks: nextStacks,
        fumigation_exercises: nextExercises,
        fumigation_exercise_stacks: nextSnapshots,
        fumigation_challenges: nextChallenges,
      },
    };
  }

  private async persistState(stateToSave: DatabaseState = this.state): Promise<void> {
    if (!this.mysqlPool) {
      throw new Error('MySQL database is not initialized.');
    }

    const connection = await this.mysqlPool.getConnection();

    try {
      await connection.beginTransaction();

      await connection.query('DELETE FROM fumigation_challenges');
      await connection.query('DELETE FROM fumigation_exercise_stacks');
      await connection.query('DELETE FROM fumigation_exercises');
      await connection.query('DELETE FROM stacks');
      await connection.query('DELETE FROM commodities');
      await connection.query('DELETE FROM officers');
      await connection.query('DELETE FROM warehouses');

      if (stateToSave.warehouses.length > 0) {
        for (const warehouse of stateToSave.warehouses) {
          await connection.query(
            `INSERT INTO warehouses (id, warehouse_code, warehouse_name, location, is_active, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [warehouse.id, warehouse.warehouse_code, warehouse.warehouse_name, warehouse.location, warehouse.is_active, warehouse.created_at, warehouse.updated_at]
          );
        }
      }

      if (stateToSave.officers.length > 0) {
        for (const officer of stateToSave.officers) {
          await connection.query(
            `INSERT INTO officers (id, employee_number, name, department, phone, is_active, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            [officer.id, officer.employee_number, officer.name, officer.department, officer.phone ?? null, officer.is_active, officer.created_at, officer.updated_at]
          );
        }
      }

      if (stateToSave.commodities.length > 0) {
        for (const commodity of stateToSave.commodities) {
          await connection.query(
            `INSERT INTO commodities (id, commodity_name, default_unit, is_active, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?)`,
            [commodity.id, commodity.commodity_name, commodity.default_unit, commodity.is_active, commodity.created_at, commodity.updated_at]
          );
        }
      }

      if (stateToSave.stacks.length > 0) {
        for (const stack of stateToSave.stacks) {
          await connection.query(
            `INSERT INTO stacks (id, warehouse_id, stack_number, commodity_id, current_quantity, unit, status, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [stack.id, stack.warehouse_id, stack.stack_number, stack.commodity_id, stack.current_quantity, stack.unit, stack.status, stack.created_at, stack.updated_at]
          );
        }
      }

      if (stateToSave.fumigation_exercises.length > 0) {
        for (const exercise of stateToSave.fumigation_exercises) {
          await connection.query(
            `INSERT INTO fumigation_exercises (id, exercise_number, warehouse_id, planned_fumigation_date, actual_fumigation_date, planned_duration, actual_duration, responsible_officer_id, status, remarks, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              exercise.id,
              exercise.exercise_number,
              exercise.warehouse_id,
              exercise.planned_fumigation_date,
              exercise.actual_fumigation_date ?? null,
              exercise.planned_duration,
              exercise.actual_duration ?? null,
              exercise.responsible_officer_id,
              exercise.status,
              exercise.remarks ?? null,
              exercise.created_at,
              exercise.updated_at,
            ]
          );
        }
      }

      if (stateToSave.fumigation_exercise_stacks.length > 0) {
        for (const snapshot of stateToSave.fumigation_exercise_stacks) {
          await connection.query(
            `INSERT INTO fumigation_exercise_stacks (id, fumigation_exercise_id, stack_id, stack_number_snapshot, commodity_id, commodity_name_snapshot, quantity_snapshot, unit_snapshot, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              snapshot.id,
              snapshot.fumigation_exercise_id,
              snapshot.stack_id,
              snapshot.stack_number_snapshot,
              snapshot.commodity_id,
              snapshot.commodity_name_snapshot,
              snapshot.quantity_snapshot,
              snapshot.unit_snapshot,
              snapshot.created_at,
            ]
          );
        }
      }

      if (stateToSave.fumigation_challenges.length > 0) {
        for (const challenge of stateToSave.fumigation_challenges) {
          await connection.query(
            `INSERT INTO fumigation_challenges (id, fumigation_exercise_id, challenge_category, description, action_resolution, resolved, resolution_date, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              challenge.id,
              challenge.fumigation_exercise_id,
              challenge.challenge_category,
              challenge.description,
              challenge.action_resolution ?? null,
              challenge.resolved,
              challenge.resolution_date ?? null,
              challenge.created_at,
              challenge.updated_at,
            ]
          );
        }
      }

      await connection.commit();
    } catch (error) {
      await connection.rollback();
      throw error;
    } finally {
      connection.release();
    }
  }

  public get isMysqlActive(): boolean {
    return this.isUsingMysql;
  }

  public getState(): DatabaseState {
    return this.state;
  }

  public resetToDefaultSeeds(): void {
    this.state = getDefaultSeedData();
    void this.persistState(this.state);
  }

  public async runTransaction<T>(work: (draft: DatabaseState) => Promise<T> | T): Promise<T> {
    const draft: DatabaseState = JSON.parse(JSON.stringify(this.state));
    try {
      const result = await work(draft);
      this.state = draft;
      await this.persistState(this.state);
      return result;
    } catch (error) {
      console.error('[Transaction Aborted & Rolled Back]', error);
      throw error;
    }
  }

  public getNowTimestamp(): string {
    const d = new Date();
    const pad = (n: number) => n.toString().padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  }
}

export const dbManager = new RelationalDatabaseManager();
